"""Offline acquisition contract tests; only generated bytes, never real HTTP."""
import hashlib
import importlib.util
import io
import json
import os
from pathlib import Path
import tempfile
from types import SimpleNamespace
import unittest
from unittest import mock


SOURCE = Path(__file__).resolve().parents[1] / 'scripts/run_conditional_residual_stage0.py'
spec = importlib.util.spec_from_file_location('stage0_acquisition_under_test', SOURCE)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


def blob_sha(body):
    return hashlib.sha1(b'blob ' + str(len(body)).encode() + b'\0' + body).hexdigest()


class FakeResponse:
    def __init__(self, body, status=200):
        self.body = io.BytesIO(body)
        self.status = status
        self.read_sizes = []
        self.payload_bytes = 0
        self.closed = False

    def read(self, n):
        self.read_sizes.append(n)
        block = self.body.read(n)
        self.payload_bytes += len(block)
        return block

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.closed = True


class AcquisitionTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='evr-0006-acq-fixture-')
        self.addCleanup(self.temp.cleanup)
        self.args = SimpleNamespace(cache=Path(self.temp.name))
        self.body = b'fixture-image'
        self.cfg = {'download_cap_per_image_bytes': 32,
                    'acquisition_old_ceiling_bytes': 100,
                    'new_metadata_allowance_bytes': 10}
        self.data = {'source_commit': 'a' * 40,
                     'images': [{'id': 'd1', 'path': 'CroppedImages/test.JPG',
                                 'bytes': len(self.body), 'git_blob_sha1': blob_sha(self.body)}]}
        self.urlopen = mock.patch.object(module.urllib.request, 'urlopen',
                                         side_effect=AssertionError('Unstubbed HTTP is forbidden')).start()
        self.addCleanup(mock.patch.stopall)

    @property
    def assets(self):
        return self.args.cache / 'assets'

    def stub(self, body=None, status=200):
        response = FakeResponse(self.body if body is None else body, status)
        self.urlopen.side_effect = None
        self.urlopen.return_value = response
        return response

    def acquire(self):
        return module.acquire(self.args, self.cfg, self.data)

    def assert_retry_blocked(self):
        old = self.urlopen.call_count
        with self.assertRaises(Exception):
            self.acquire()
        self.assertEqual(self.urlopen.call_count, old)

    def test_pinned_url_git_blob_size_and_budget(self):
        response = self.stub()
        ledger = self.acquire()
        expected = ('https://raw.githubusercontent.com/csjunxu/PolyU-Real-World-Noisy-Images-Dataset/'
                    + 'a' * 40 + '/CroppedImages/test.JPG')
        self.urlopen.assert_called_once_with(expected, timeout=30)
        self.assertTrue(response.closed)
        self.assertEqual((self.assets / 'test.JPG').read_bytes(), self.body)
        self.assertEqual(ledger['data_payload_bytes'], len(self.body))
        self.assertEqual(ledger['conservative_ceiling_bytes'], 110 + len(self.body))
        self.assertEqual(ledger['assets'][0]['git_blob_sha1'], blob_sha(self.body))
        self.assertEqual(ledger['assets'][0]['sha256'], hashlib.sha256(self.body).hexdigest())
        self.assertEqual(ledger['assets'][0]['attempts'], 1)

    def test_completed_cache_hit_never_repeats_get(self):
        self.stub()
        before = self.acquire()
        after = self.acquire()
        self.assertEqual(before, after)
        self.assertEqual(self.urlopen.call_count, 1)

    def test_started_marker_forbids_get(self):
        self.assets.mkdir()
        (self.assets / 'd1.started.json').write_text('{}')
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.urlopen.assert_not_called()

    def test_orphan_partial_forbids_get(self):
        self.assets.mkdir()
        partial = self.assets / 'test.partial'
        partial.write_bytes(b'preserved')
        self.stub()
        with self.assertRaises(Exception):
            self.acquire()
        self.assertEqual(partial.read_bytes(), b'preserved')
        self.urlopen.assert_not_called()

    def test_orphan_receipt_forbids_get(self):
        self.assets.mkdir()
        (self.assets / 'd1.json').write_text('{}')
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.urlopen.assert_not_called()

    def test_cache_without_receipt_rejected(self):
        self.assets.mkdir()
        (self.assets / 'test.JPG').write_bytes(self.body)
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.urlopen.assert_not_called()

    def test_tampered_cache_body_rejected(self):
        self.stub()
        self.acquire()
        (self.assets / 'test.JPG').write_bytes(b'wrong')
        self.assert_retry_blocked()

    def test_receipt_identity_and_bytes_cannot_override_verified_body(self):
        self.assets.mkdir()
        (self.assets / 'test.JPG').write_bytes(self.body)
        # A completed-looking receipt with correct SHA but wrong frozen identity.
        (self.assets / 'd1.json').write_text(json.dumps({
            'id': 'wrong-id', 'bytes': 0, 'sha256': hashlib.sha256(self.body).hexdigest(),
            'git_blob_sha1': '0' * 40, 'source_url': 'https://wrong.invalid/',
            'attempts': 1, 'finished_utc': '2000-01-01T00:00:00+00:00'}))
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.urlopen.assert_not_called()

    def test_short_body_preserves_attempt_and_forbids_retry(self):
        self.stub(b'x')
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.assertEqual((self.assets / 'test.partial').read_bytes(), b'x')
        self.assertTrue((self.assets / 'd1.started.json').exists())
        self.assertFalse((self.assets / 'test.JPG').exists())
        self.assert_retry_blocked()

    def test_wrong_blob_preserves_attempt_and_forbids_retry(self):
        wrong = b'x' * len(self.body)
        self.stub(wrong)
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.assertEqual((self.assets / 'test.partial').read_bytes(), wrong)
        self.assertTrue((self.assets / 'd1.started.json').exists())
        self.assertFalse((self.assets / 'test.JPG').exists())
        self.assert_retry_blocked()

    def test_overlong_preserves_failure_and_forbids_retry(self):
        self.stub(self.body + b'x' * 100)
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.assertTrue((self.assets / 'test.partial').exists())
        self.assertTrue((self.assets / 'd1.started.json').exists())
        self.assertFalse((self.assets / 'test.JPG').exists())
        self.assert_retry_blocked()

    def test_overlong_response_is_bounded_by_one_byte_sentinel(self):
        response = self.stub(self.body + b'x' * 100)
        with self.assertRaises(RuntimeError):
            self.acquire()
        # At most one extra byte is necessary to detect an overlong body.
        self.assertLessEqual(response.payload_bytes, len(self.body) + 1)

    def test_declared_size_above_per_image_cap_stops_before_get(self):
        self.cfg['download_cap_per_image_bytes'] = len(self.body) - 1
        self.stub()
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.urlopen.assert_not_called()

    def test_impossible_total_budget_stops_before_get(self):
        self.cfg['acquisition_old_ceiling_bytes'] = 10 * 1024**3 - 10 - len(self.body) + 1
        self.stub()
        with self.assertRaises(RuntimeError):
            self.acquire()
        self.urlopen.assert_not_called()

    def test_two_asset_total_budget_and_no_repeat(self):
        second = b'another'
        self.data['images'].append({'id': 'd2', 'path': 'CroppedImages/other.JPG',
                                    'bytes': len(second), 'git_blob_sha1': blob_sha(second)})
        self.urlopen.side_effect = [FakeResponse(self.body), FakeResponse(second)]
        ledger = self.acquire()
        self.assertEqual(ledger['data_payload_bytes'], len(self.body) + len(second))
        self.assertEqual(ledger['conservative_ceiling_bytes'], 110 + len(self.body) + len(second))
        self.assertEqual(self.acquire(), ledger)
        self.assertEqual(self.urlopen.call_count, 2)


if __name__ == '__main__':
    unittest.main(verbosity=2)
